    "name": "qualoraçãodeprecios",
    "description": "Quando o cliente pergunta sobre preços",
    "parameters": [
      {
        "name": "preço_minimo",
        "type": "NUMBER",
        "description": "Preço mínimo oferecido",
        "default_value": "50.00"
      }
    ]
  }
}
```

