## 💻 Exemplo de Código de Integração Webhook

Este código representa a lógica do webhook que receberá as requisições do Dialogflow:

### Backend Express.js + Node.js (Webhook Handler)

```javascript
// server.js
const express = require('express');
const axios = require('axios');
const app = express();
app.use(express.json());

const dialogflowApiKey = 'SUA_API_KEY_AQUI'; // Preencha com sua chave
const projectId = 'SEU_PROJETO'; // Identificador do projeto no console
const webhookUrl = `https://dialogflow.googleapis.com/v2/projects/${projectId}/agents/atendimentobot/agent?versionId=1`;

// Função principal de resposta
async function getResponse(queryResult) {
  const session = queryResult.session ? queryResult.session : 'sessao_padrao';

  try {
    // Chamada ao Dialogflow para obter respostas
    const response = await axios.get(`${webhookUrl}`, {
      params: {
        session_id: session,
        query_input: queryResult.queryText
      },
      headers: {
        Authorization: `Bearer ${dialogflowApiKey}`
      }
    });

    return response.data;
  } catch (error) {
    console.error('Erro na resposta:', error);
    return {
      response: "Desculpe, ocorreu um erro. Por favor, tente novamente mais tarde."
    };
  }
}

// Endpoint para receber mensagens via HTTP
app.post('/api/webhook', async (req, res) => {
  const queryResult = req.body; // Recebe o payload do Dialogflow

  const result = await getResponse(queryResult);

  if (result) {
    return res.send(result);
  } else {
    return res.send({
      responses: [
        {
          content: "Desculpe, ocorreu um erro. Por favor, tente novamente mais tarde.",
          speech: "Desculpe, ocorreu um erro."
        }
      ],
      outputContext: ''
    });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Servidor rodando na porta ${PORT}`);
});
```

